//! Experiment 46: automatic ids and UUIDs. Insert cost of an automatic key vs an explicit one (1, 8, 64 threads), of a
//! UNIQUE UUID column filled by uuid() (v7, time-ordered) vs gen_random_uuid() (v4, random), and lookups by id, by UUID
//! through the unique index, and by UUID with a scan. SQLite reference: INTEGER PRIMARY KEY with NULL ids, and a UUID
//! column (16-byte BLOB, generated by the application) with a UNIQUE index.
use rusqlite::{params, Connection};
use sqweezdb::config::{Config, SnapshotPolicy};
use sqweezdb::sql::{Session, Sql};
use sqweezdb::table::{format_uuid, uuid_v4, uuid_v7, Value};
use std::sync::{Arc, Barrier};
use std::time::Instant;

const N: i64 = 1_000_000; const ROOT: &str = "data/nocow/e46";
fn cfg() -> Config { Config { snapshot: SnapshotPolicy { log_bytes: None, idle_after: None }, ..Config::default() } }
fn fresh(name: &str) -> Arc<Sql> { let d = std::path::Path::new(ROOT).join(name); let _ = std::fs::remove_dir_all(&d); Sql::open_with(&d, cfg()).unwrap() }
fn pr(label: &str, n: i64, el: f64) { println!("{label:<74} {:>7.2} us/row {:>11.0} rows/s", el * 1e6 / n as f64, n as f64 / el); }
fn load(sql: &Sql, stmt: &str, n: i64, row: impl Fn(i64) -> Vec<Value>) -> f64 {
    let p = sql.prepare(stmt).unwrap(); let mut s = Session::default(); let t = Instant::now();
    for i in 0..n { if i % 1000 == 0 { sql.exec_s(&mut s, "BEGIN", &[]).unwrap(); } sql.execute_s(&mut s, &p, &row(i)).unwrap(); if i % 1000 == 999 || i == n - 1 { sql.exec_s(&mut s, "COMMIT", &[]).unwrap(); } }
    t.elapsed().as_secs_f64()
}
fn parallel(sql: &Arc<Sql>, threads: usize, per: i64, stmt: &'static str, row: fn(usize, i64) -> Vec<Value>) -> f64 {
    let b = Arc::new(Barrier::new(threads + 1));
    let hs: Vec<_> = (0..threads).map(|k| { let (sql, b) = (sql.clone(), b.clone()); std::thread::spawn(move || { let p = sql.prepare(stmt).unwrap(); let mut s = Session::default(); b.wait(); for i in 0..per { sql.execute_s(&mut s, &p, &row(k, i)).unwrap(); } }) }).collect();
    b.wait(); let t = Instant::now(); for h in hs { h.join().unwrap(); } t.elapsed().as_secs_f64()
}
fn main() {
    println!("=== E46: automatic ids and UUIDs (1M rows, in-process, not durable) ===");
    // ---- 1. automatic vs explicit keys, one thread, 1000-row transactions
    let a = fresh("explicit"); a.exec_s(&mut Session::default(), "CREATE TABLE t(id INT PRIMARY KEY, name VARCHAR(16))", &[]).unwrap();
    pr("ours: explicit id, 1 thread", N, load(&a, "INSERT INTO t VALUES (?, ?)", N, |i| vec![Value::Int(i + 1), Value::Text(format!("n{i}"))]));
    let b = fresh("auto"); b.exec_s(&mut Session::default(), "CREATE TABLE t(id SERIAL PRIMARY KEY, name VARCHAR(16))", &[]).unwrap();
    pr("ours: automatic id, 1 thread", N, load(&b, "INSERT INTO t (name) VALUES (?)", N, |i| vec![Value::Text(format!("n{i}"))]));
    let mut s = Session::default(); let r = b.exec_s(&mut s, "SELECT count(*), min(id), max(id) FROM t", &[]).unwrap(); println!("    automatic ids issued: count {:?}, min {:?}, max {:?} (expect 1000000, 1, 1000000)", r[0][0], r[0][1], r[0][2]);
    // ---- 2. many writers, autocommit
    for threads in [8usize, 64] {
        let per = 400_000 / threads as i64;
        let e = fresh(&format!("explicit{threads}")); e.exec_s(&mut Session::default(), "CREATE TABLE t(id INT PRIMARY KEY, name VARCHAR(16))", &[]).unwrap();
        pr(&format!("ours: explicit id, {threads} writers, autocommit"), per * threads as i64, parallel(&e, threads, per, "INSERT INTO t VALUES (?, ?)", |k, i| vec![Value::Int(k as i64 * 1_000_000 + i + 1), Value::Text("x".into())]));
        let au = fresh(&format!("auto{threads}")); au.exec_s(&mut Session::default(), "CREATE TABLE t(id SERIAL PRIMARY KEY, name VARCHAR(16))", &[]).unwrap();
        pr(&format!("ours: automatic id, {threads} writers, autocommit"), per * threads as i64, parallel(&au, threads, per, "INSERT INTO t (name) VALUES (?)", |_, _| vec![Value::Text("x".into())]));
        let r = au.exec_s(&mut Session::default(), "SELECT count(*), max(id) FROM t", &[]).unwrap(); println!("    {threads} writers: {:?} rows, max id {:?} (no gaps, no duplicates)", r[0][0], r[0][1]);
    }
    // ---- 3. UUID columns
    let mut by_id_uuid = vec![];
    for (label, ddl) in [("uuid() (v7, time-ordered)", "CREATE TABLE u(id SERIAL PRIMARY KEY, uid UUID UNIQUE NOT NULL DEFAULT uuid(), name VARCHAR(16))"), ("gen_random_uuid() (v4, random)", "CREATE TABLE u(id SERIAL PRIMARY KEY, uid UUID UNIQUE NOT NULL DEFAULT gen_random_uuid(), name VARCHAR(16))")] {
        let u = fresh(if label.starts_with("uuid()") { "v7" } else { "v4" }); u.exec_s(&mut Session::default(), ddl, &[]).unwrap();
        pr(&format!("ours: automatic id + UNIQUE UUID by {label}, 1 thread"), N, load(&u, "INSERT INTO u (name) VALUES (?)", N, |i| vec![Value::Text(format!("n{i}"))]));
        if by_id_uuid.is_empty() { let rows = u.exec_s(&mut Session::default(), "SELECT id, uid FROM u WHERE id <= 200000", &[]).unwrap(); by_id_uuid = rows.into_iter().map(|r| (r[0].clone(), r[1].clone())).collect(); 
            let pid = u.prepare("SELECT name FROM u WHERE id = ?").unwrap(); let puid = u.prepare("SELECT name FROM u WHERE uid = ?").unwrap(); let mut s = Session::default();
            let t = Instant::now(); for k in 0..200_000usize { let (id, _) = &by_id_uuid[(k * 7919) % by_id_uuid.len()]; assert_eq!(u.execute_s(&mut s, &pid, &[id.clone()]).unwrap().len(), 1); } pr("ours: point read by id", 200_000, t.elapsed().as_secs_f64());
            let t = Instant::now(); for k in 0..200_000usize { let (_, uid) = &by_id_uuid[(k * 7919) % by_id_uuid.len()]; assert_eq!(u.execute_s(&mut s, &puid, &[uid.clone()]).unwrap().len(), 1); } pr("ours: point read by UUID (text parameter, unique index)", 200_000, t.elapsed().as_secs_f64());
            u.exec_s(&mut s, "ALTER TABLE u ADD COLUMN other UUID NOT NULL DEFAULT gen_random_uuid()", &[]).unwrap();
            let some: Vec<Value> = u.exec_s(&mut s, "SELECT other FROM u WHERE id <= 20", &[]).unwrap().into_iter().map(|mut r| r.remove(0)).collect();
            let po = u.prepare("SELECT name FROM u WHERE other = ?").unwrap(); let t = Instant::now(); for k in 0..20 { assert_eq!(u.execute_s(&mut s, &po, &[some[k].clone()]).unwrap().len(), 1); } pr("ours: read by UUID without an index (full scan of 1M rows)", 20, t.elapsed().as_secs_f64());
        }
    }
    // ---- 4. SQLite reference
    let path = format!("{ROOT}/ref.db"); for suf in ["", "-wal", "-shm"] { let _ = std::fs::remove_file(format!("{path}{suf}")); }
    let c = Connection::open(&path).unwrap(); c.execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=OFF; PRAGMA cache_size=-262144;").unwrap();
    c.execute_batch("CREATE TABLE t(id INTEGER PRIMARY KEY, name TEXT); CREATE TABLE u(id INTEGER PRIMARY KEY, uid BLOB NOT NULL UNIQUE, name TEXT)").unwrap();
    let mut ins = |sql: &str, f: &dyn Fn(i64, &mut rusqlite::Statement) | -> f64 { let t = Instant::now(); let mut st = c.prepare(sql).unwrap(); for i in 0..N { if i % 1000 == 0 { c.execute_batch("BEGIN").unwrap(); } f(i, &mut st); if i % 1000 == 999 { c.execute_batch("COMMIT").unwrap(); } } t.elapsed().as_secs_f64() };
    pr("SQLite: INTEGER PRIMARY KEY given as NULL (automatic), 1 thread", N, ins("INSERT INTO t (name) VALUES (?)", &|i, st| { st.execute(params![format!("n{i}")]).unwrap(); }));
    pr("SQLite: + UNIQUE 16-byte UUID v7 made by the application", N, ins("INSERT INTO u (uid, name) VALUES (?, ?)", &|i, st| { st.execute(params![&uuid_v7()[..], format!("n{i}")]).unwrap(); }));
    let keys: Vec<Vec<u8>> = { let mut st = c.prepare("SELECT uid FROM u WHERE id <= 200000").unwrap(); st.query_map([], |r| r.get::<_, Vec<u8>>(0)).unwrap().map(|r| r.unwrap()).collect() };
    let mut st = c.prepare("SELECT name FROM u WHERE id = ?").unwrap(); let t = Instant::now(); for k in 0..200_000i64 { let _: String = st.query_row(params![(k * 7919) % 200_000 + 1], |r| r.get(0)).unwrap(); } pr("SQLite: point read by id", 200_000, t.elapsed().as_secs_f64());
    let mut st = c.prepare("SELECT name FROM u WHERE uid = ?").unwrap(); let t = Instant::now(); for k in 0..200_000usize { let _: String = st.query_row(params![&keys[(k * 7919) % keys.len()][..]], |r| r.get(0)).unwrap(); } pr("SQLite: point read by UUID (16-byte BLOB, UNIQUE index)", 200_000, t.elapsed().as_secs_f64());
    // ---- 5. the generators themselves
    let t = Instant::now(); let mut x = 0u8; for _ in 0..1_000_000 { x ^= uuid_v7()[15]; } pr(&format!("uuid_v7() alone (check {x})"), 1_000_000, t.elapsed().as_secs_f64());
    let t = Instant::now(); for _ in 0..1_000_000 { x ^= uuid_v4()[15]; } pr(&format!("uuid_v4() alone (check {x})"), 1_000_000, t.elapsed().as_secs_f64());
    let b = Arc::new(Barrier::new(9)); let hs: Vec<_> = (0..8).map(|_| { let b = b.clone(); std::thread::spawn(move || { b.wait(); let mut v = Vec::with_capacity(250_000); for _ in 0..250_000 { v.push(uuid_v7()); } v }) }).collect(); b.wait();
    let t = Instant::now(); let mut all: Vec<[u8; 16]> = hs.into_iter().flat_map(|h| h.join().unwrap()).collect(); let el = t.elapsed().as_secs_f64(); pr("uuid_v7() on 8 threads at once (one shared ordering counter)", 2_000_000, el);
    let n = all.len(); all.sort(); all.dedup(); println!("    8 threads x 250k v7 UUIDs: {} distinct of {n}; example {}", all.len(), format_uuid(&all[0]));
    let _ = std::fs::remove_dir_all(ROOT);   // the connection closes at the end of main
}
